:root{--purple:#6f4bf6;--purple-dark:#5334d0;--ink:#121116;--muted:#77747d;--line:#e4e2e7}*{box-sizing:border-box}html,body{min-width:320px;min-height:100%;margin:0}body{color:var(--ink);font:15px/1.5 "DM Sans",Arial,sans-serif;background:#fff}.auth-shell{display:grid;min-height:100dvh;grid-template-columns:minmax(360px,44%) minmax(0,1fr)}.visual{position:relative;display:flex;min-height:100dvh;flex-direction:column;justify-content:space-between;overflow:hidden;padding:42px;color:#fff;background:linear-gradient(180deg,rgba(4,28,45,.17) 0%,rgba(4,28,45,.04) 43%,rgba(4,28,45,.84) 100%),url("{{ asset('assets/transglobe/admin/admin-login-travel.jpg') }}") center/cover no-repeat}.visual:before{position:absolute;inset:0;background:linear-gradient(100deg,rgba(3,23,37,.38),transparent 58%);content:""}.brand,.quote{position:relative;z-index:1}.brand{display:inline-flex;align-items:center;gap:10px;width:max-content;color:#fff;font-size:18px;font-weight:700;letter-spacing:-.035em;text-decoration:none}.brand-mark{display:grid;width:28px;height:28px;grid-template-columns:repeat(2,1fr);gap:3px;transform:rotate(45deg)}.brand-mark i{display:block;border-radius:50%;background:currentColor}.quote{max-width:360px}.quote p{margin:0;font-size:clamp(29px,3vw,42px);font-weight:700;line-height:1.1;letter-spacing:-.06em}.quote span{display:block;margin-top:15px;max-width:300px;color:rgba(255,255,255,.88);font-size:13px;line-height:1.55}.form-pane{display:flex;min-width:0;min-height:100dvh;align-items:center;justify-content:center;padding:40px 56px;background:#fff}.form-wrap{width:min(100%,390px)}h1{margin:0;color:#09090c;font-size:31px;font-weight:700;letter-spacing:-.06em;line-height:1.13;text-align:center}.intro{margin:10px auto 28px;max-width:330px;color:var(--muted);font-size:13px;line-height:1.55;text-align:center}.error{display:flex;gap:8px;margin:0 0 15px;padding:10px 11px;border:1px solid #f1c3c3;border-radius:9px;background:#fff2f2;color:#a72525;font-size:12px;font-weight:600}.error svg{width:17px;height:17px;flex:none}.field{position:relative;margin-top:13px}.field label{position:absolute;z-index:1;top:8px;left:13px;color:#77747d;font-size:10px;font-weight:500}.field input{width:100%;height:52px;padding:21px 40px 5px 13px;border:1px solid var(--line);border-radius:9px;background:#fff;color:#16141b;font:14px/1.2 "DM Sans",Arial,sans-serif;outline:none;transition:border-color .16s ease,box-shadow .16s ease}.field input::placeholder{color:#b4b1b8}.field input:focus{border-color:var(--purple);box-shadow:0 0 0 3px rgba(111,75,246,.16)}.field input[aria-invalid="true"]{border-color:#c52d2d}.toggle-password{position:absolute;right:5px;bottom:4px;display:grid;width:41px;height:41px;place-items:center;border:0;border-radius:8px;background:transparent;color:#77747d;cursor:pointer;touch-action:manipulation}.toggle-password:hover{background:#f3f1ff;color:var(--purple)}.toggle-password svg{width:19px;height:19px}.forgot{display:inline-block;margin:10px 0 15px;color:var(--purple-dark);font-size:12px;font-weight:700;text-decoration:none}.forgot:hover{text-decoration:underline}.remember{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:0 0 20px;color:#7c7881;font-size:13px}.switch{position:relative;display:inline-flex;width:44px;height:28px;flex:none;cursor:pointer}.switch input{position:absolute;width:1px;height:1px;opacity:0}.slider{position:absolute;inset:0;border-radius:999px;background:#d9d7df;box-shadow:inset 0 0 0 1px rgba(0,0,0,.05);transition:background .16s ease}.slider:before{position:absolute;top:4px;left:4px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 2px 5px rgba(18,17,22,.2);content:"";transition:transform .16s ease}.switch input:checked+.slider{background:var(--purple)}.switch input:checked+.slider:before{transform:translateX(16px)}.switch input:focus-visible+.slider{outline:3px solid rgba(111,75,246,.3);outline-offset:3px}.submit{display:flex;width:100%;min-height:48px;align-items:center;justify-content:center;gap:8px;border:0;border-radius:999px;background:linear-gradient(90deg,var(--purple-dark),var(--purple));box-shadow:0 9px 18px rgba(111,75,246,.22);color:#fff;cursor:pointer;font:700 14px/1 "DM Sans",Arial,sans-serif;touch-action:manipulation;transition:transform .16s ease,box-shadow .16s ease}.submit:hover{box-shadow:0 12px 21px rgba(111,75,246,.3);transform:translateY(-1px)}.submit:disabled{cursor:wait;opacity:.75;transform:none}.submit svg{width:17px;height:17px}.divider{display:flex;align-items:center;gap:10px;margin:24px 0 18px;color:#918e96;font-size:10px;font-weight:600}.divider:before,.divider:after{height:1px;flex:1;background:#ebe9ee;content:""}.secure{display:flex;width:100%;min-height:44px;align-items:center;justify-content:center;gap:9px;border-radius:999px;background:#f7f7fa;color:#3d3943;font-size:12px;font-weight:700}.secure svg{width:18px;height:18px;color:var(--purple)}.back{display:block;margin-top:25px;color:#8a8790;font-size:12px;text-align:center;text-decoration:none}.back:hover{color:var(--purple-dark)}.toggle-password:focus-visible,.submit:focus-visible,.forgot:focus-visible,.back:focus-visible,.brand:focus-visible{outline:3px solid rgba(111,75,246,.36);outline-offset:3px}@media(max-width:760px){.auth-shell{grid-template-columns:1fr;grid-template-rows:minmax(170px,30dvh) auto}.visual{min-height:0;padding:24px;background-position:center 64%}.quote{max-width:300px}.quote p{font-size:25px}.quote span{display:none}.form-pane{min-height:0;align-items:flex-start;padding:32px 24px 38px}.form-wrap{margin:auto}.intro{margin-bottom:23px}.divider,.secure{display:none}.back{margin-top:23px}}@media(max-height:650px) and (min-width:761px){.visual{padding:28px}.quote p{font-size:29px}.form-pane{padding-block:24px}.intro{margin-bottom:18px}.divider{margin:16px 0 13px}.back{margin-top:17px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important}}
.visual{background:#082d45}.visual-slide{position:absolute;inset:0;opacity:0;background:center/cover no-repeat;transform:scale(1.025);transition:opacity .7s ease,transform 6.8s ease}.visual-slide.is-active{opacity:1;transform:scale(1)}.visual:before{z-index:1;background:linear-gradient(180deg,rgba(4,28,45,.22) 0%,rgba(4,28,45,.08) 45%,rgba(4,28,45,.86) 100%)}.brand,.quote,.slide-controls{z-index:2}.quote{min-height:152px}.slide-controls{position:relative;display:flex;gap:8px;margin-top:24px}.slide-controls button{width:10px;height:10px;padding:0;border:1px solid rgba(255,255,255,.85);border-radius:999px;background:transparent;cursor:pointer;transition:width .2s ease,background .2s ease}.slide-controls button[aria-pressed="true"]{width:28px;background:#fff}.slide-controls button:focus-visible{outline:3px solid rgba(255,255,255,.7);outline-offset:4px}@media(max-width:760px){.quote{min-height:78px}.slide-controls{margin-top:14px}}@media(prefers-reduced-motion:reduce){.visual-slide,.slide-controls button{transition:none!important}}</style></head>
