</main><script>const toggle=document.querySelector('.toggle-password'),password=document.getElementById('password');toggle?.addEventListener('click',()=>{const visible=password.type==='text';password.type=visible?'password':'text';toggle.setAttribute('aria-pressed',String(!visible));toggle.setAttribute('aria-label',visible?'Show password':'Hide password')});document.getElementById('admin-login-form')?.addEventListener('submit',event=>{const button=event.currentTarget.querySelector('.submit');if(!event.currentTarget.checkValidity()||button.disabled)return;button.disabled=true;button.querySelector('span').textContent='Logging in...'});;const slider=document.querySelector('.visual'),slides=[...document.querySelectorAll('.visual-slide')],slideButtons=[...document.querySelectorAll('[data-slide-index]')],slideTitle=document.querySelector('[data-slide-title]'),slideCaption=document.querySelector('[data-slide-caption]');if(slider&&slides.length){let current=0,timer;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');const show=index=>{current=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('is-active',i===current));slideButtons.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===current)));slideTitle.textContent=slides[current].dataset.title;slideCaption.textContent=slides[current].dataset.caption};const stop=()=>{if(timer){window.clearInterval(timer);timer=undefined}};const start=()=>{stop();if(!reduced.matches)timer=window.setInterval(()=>show(current+1),6500)};slideButtons.forEach(button=>button.addEventListener('click',()=>{show(Number(button.dataset.slideIndex));start()}));slider.addEventListener('pointerenter',stop);slider.addEventListener('pointerleave',start);reduced.addEventListener?.('change',start);start()};</script></body></html>
